_install('astdata', '"""Lossless top-down encoding of Python ASTs, shared by the latent tree model and the transformer baseline.\n\nEvery child slot is one UNIT, in pre-order (a unit is emitted, then the subtree of its child, then the next slot;\na list field ends with a <STOP> unit; an empty optional AST field is a <NONE> unit).  Per unit:\n  ufile file id                     x     child symbol id (Name ids and Constant kinds folded in; rare -> <OTHER>)\n  t     context id (parent type.field) dp    depth of the parent (root Module = 0)\n  par   node index of the parent       node  node index of the child (-1 for <STOP>/<NONE>)\nPer node: depth, file, internal (has units below it).  Roots (one Module per file) are nodes without a unit.\nThe same units as verify/code_claim1.py, so an H = 1 model reproduces its numbers exactly.\n"""\nimport ast, glob, os, sys\nfrom collections import Counter\nimport numpy as np\n\nHERE = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else "."\nCACHE = os.path.join(HERE, "astcache.npz")\nMIN_COUNT = 200\n\n\ndef child_sym(n):\n    if isinstance(n, ast.Name): return "N:" + n.id\n    if isinstance(n, ast.Constant): return "C:" + type(n.value).__name__\n    return type(n).__name__\n\n\ndef optional_fields():\n    opt = {}\n    for name in dir(ast):\n        cls = getattr(ast, name)\n        if isinstance(cls, type) and issubclass(cls, ast.AST):\n            fs = [f for f, ty in getattr(cls, "_field_types", {}).items() if str(ty).startswith("ast.") and "None" in str(ty)]\n            if fs: opt[name] = tuple(fs)\n    return opt\n\n\ndef encode_file(tree, fi, node0, OPT):\n    """returns unit rows (file, ctx, sym, dp, par, node) and node rows (depth, internal), node ids from node0"""\n    units, nodes = [], [[0, 0]]                      # root\n    def walk(nd, nid, k):\n        for fld, val in ast.iter_fields(nd):\n            ctx = type(nd).__name__ + "." + fld\n            if isinstance(val, list):\n                if val and not isinstance(val[0], ast.AST):\n                    continue\n                for c in val:\n                    if isinstance(c, ast.AST) and not isinstance(c, ast.expr_context):\n                        emit(c, ctx, nid, k)\n                units.append((fi, ctx, "<STOP>", k, nid, -1))\n            elif isinstance(val, ast.AST):\n                if not isinstance(val, ast.expr_context):\n                    emit(val, ctx, nid, k)\n            elif val is None and fld in OPT.get(type(nd).__name__, ()):\n                units.append((fi, ctx, "<NONE>", k, nid, -1))\n    def emit(c, ctx, pid, k):\n        cid = node0 + len(nodes); nodes.append([k + 1, 0])\n        units.append((fi, ctx, child_sym(c), k, pid, cid))\n        n_before = len(units)\n        walk(c, cid, k + 1)\n        if len(units) > n_before:\n            nodes[cid - node0][1] = 1\n    walk(tree, node0, 0)\n    if units: nodes[0][1] = 1\n    return units, nodes\n\n\ndef build():\n    lib = os.path.dirname(os.__file__)\n    files = sorted(f for f in glob.glob(os.path.join(lib, "**", "*.py"), recursive=True) if "site-packages" not in f)\n    sys.setrecursionlimit(20000)\n    OPT = optional_fields()\n    U, N, NF = [], [], []\n    for fi, f in enumerate(files):\n        try:\n            with open(f, "rb") as fh:\n                tr = ast.parse(fh.read())\n            u, n = encode_file(tr, fi, len(N), OPT)\n        except (SyntaxError, ValueError, RecursionError, MemoryError):\n            continue\n        U += u; N += n; NF += [fi] * len(n)\n    cnt = Counter(r[2] for r in U)\n    keep = sorted(w for w, n in cnt.items() if n >= MIN_COUNT)\n    sym = keep + ["<OTHER>"]; sv = {w: i for i, w in enumerate(sym)}\n    ctxs = sorted({r[1] for r in U}); tv = {w: i for i, w in enumerate(ctxs)}\n    d = dict(\n        ufile=np.array([r[0] for r in U], np.int32), t=np.array([tv[r[1]] for r in U], np.int16),\n        x=np.array([sv.get(r[2], len(sym) - 1) for r in U], np.int16), dp=np.array([r[3] for r in U], np.int16),\n        par=np.array([r[4] for r in U], np.int32), node=np.array([r[5] for r in U], np.int32),\n        node_depth=np.array([n[0] for n in N], np.int16), node_internal=np.array([n[1] for n in N], np.int8),\n        node_file=np.array(NF, np.int32), symbols=np.array(sym), contexts=np.array(ctxs))\n    return d\n\n\ndef load(path=CACHE):\n    if not os.path.exists(path):\n        np.savez_compressed(path, **build())\n    z = np.load(path, allow_pickle=False)\n    return {k: z[k] for k in z.files}\n\n\ndef split(d, seed=0):\n    """the test/pool split of code_claim1.py: first half of a seed-0 permutation of the parsed file ids is test"""\n    files = np.unique(d["ufile"])\n    perm = np.random.default_rng(seed).permutation(files)\n    return perm[: len(files) // 2], perm[len(files) // 2:]\n\n\nif __name__ == "__main__":\n    d = load()\n    print({k: (v.shape, v.dtype) for k, v in d.items()}, os.path.getsize(CACHE) / 1e6, "MB")\n')
_install('code_latent', '"""Latent tied tree model of Python ASTs (where.tex sec. prog-latent), fitted by EM with zero labels.\n\nEvery node n carries a hidden type h_n in {0..H-1}.  A child slot u of parent p, with context t_u and parent-depth\ngroup g_u, draws its symbol and (if the child is an internal node) the child\'s type:\n    P(x_u | g_u, t_u, h_p) * Q(h_u | g_u, x_u, h_p)\n<STOP>/<NONE> slots and leaf children draw only the symbol (a leaf\'s type has no observable consequence).\nRoots draw h from pi.  Groups: \'partial\' = parent depth 0, 1, 2 own rules, >= 3 one tied rule; \'tied\' = one rule.\nH = 1 is exactly the observed-rule model of code_claim1.py.\n\nE-step: one upward pass (log messages, level by level) and one downward pass, both exact (sum-product on a tree).\nM-step: closed form, with the smoothing of code_claim1.py for P and a small Dirichlet for Q.\n"""\nimport math\nimport numpy as np\nimport torch\n\nBANDS_DP_GROUP = {"partial": lambda dp: np.minimum(dp, 3), "tied": lambda dp: np.zeros_like(dp)}\n\n\nclass Corpus:\n    """the units and nodes of a set of files, re-indexed contiguously, as torch tensors on `dev`"""\n    def __init__(self, d, files, dev, grouping="partial"):\n        um = np.isin(d["ufile"], files); nm = np.isin(d["node_file"], files)\n        gidx = np.nonzero(nm)[0]\n        loc = np.full(len(d["node_depth"]), -1, np.int64); loc[gidx] = np.arange(len(gidx))\n        node = d["node"][um].astype(np.int64)\n        node_l = np.where(node >= 0, loc[np.maximum(node, 0)], -1)\n        internal = np.where(node >= 0, d["node_internal"][np.maximum(node, 0)], 0).astype(bool)\n        dp = d["dp"][um].astype(np.int64)\n        ndepth = d["node_depth"][nm]\n        roots = np.nonzero(ndepth == 0)[0]\n        nfile = d["node_file"][nm]\n        rootpos = {f: i for i, f in enumerate(nfile[roots])}\n        T = lambda a: torch.as_tensor(np.ascontiguousarray(a), device=dev)\n        self.n_units, self.n_nodes, self.n_files = int(um.sum()), int(nm.sum()), len(roots)\n        self.t, self.x = T(d["t"][um].astype(np.int64)), T(d["x"][um].astype(np.int64))\n        self.g = T(BANDS_DP_GROUP[grouping](dp).astype(np.int64))\n        self.par, self.node = T(loc[d["par"][um]]), T(node_l)\n        self.internal = T(internal)\n        self.roots = T(roots.astype(np.int64))\n        self.node_fidx = T(np.array([rootpos[f] for f in nfile], np.int64))\n        self.lev = [T(np.nonzero(dp == k)[0]) for k in range(int(dp.max()) + 1)]\n        self.xcount = np.bincount(d["x"][um], minlength=len(d["symbols"]))\n\n\nclass LatentTree:\n    def __init__(self, G, T, C, H, dev, a=1.0, b=0.01):\n        self.G, self.T, self.C, self.H, self.dev, self.a, self.b = G, T, C, H, dev, a, b\n        self.logP = torch.full((G, T, C, H), -math.log(C), device=dev)\n        self.logQ = torch.full((G, C, H, H), -math.log(H), device=dev)\n        self.logpi = torch.full((H,), -math.log(H), device=dev)\n        self.m = None                                             # training marginal of x, for smoothing\n        self.max_elems = 1.5e8                                    # cap on the (m, H, H) blocks of the passes\n\n    def chunk(self):\n        return max(1, int(self.max_elems // (self.H * self.H)))\n\n    # ------------------------------------------------------------------ inference\n    def upward(self, c):\n        logb = torch.zeros(c.n_nodes, self.H, device=self.dev)\n        LM = torch.empty(c.n_units, self.H, device=self.dev)\n        for u in reversed(c.lev):\n            if len(u) == 0: continue\n            g, t, x = c.g[u], c.t[u], c.x[u]\n            lm = self.logP[g, t, x].clone()                          # (n, H) over the parent\'s type\n            ii = torch.nonzero(c.internal[u])[:, 0]\n            for j in ii.split(self.chunk()):                         # (m, H, H) blocks, bounded memory\n                q = self.logQ[g[j], x[j]]\n                lm[j] = lm[j] + torch.logsumexp(q + logb[c.node[u[j]]][:, None, :], dim=2)\n            LM[u] = lm\n            logb.index_add_(0, c.par[u], lm)\n        Z = torch.logsumexp(self.logpi + logb[c.roots], dim=1)       # log-likelihood per file\n        return logb, LM, Z\n\n    def loglik(self, c):\n        return float(self.upward(c)[2].double().sum())\n\n    def estep(self, c):\n        logb, LM, Z = self.upward(c)\n        Zn = Z[c.node_fidx]\n        logo = torch.full((c.n_nodes, self.H), -math.inf, device=self.dev)\n        logo[c.roots] = self.logpi\n        cP = torch.zeros_like(self.logP); cQ = torch.zeros_like(self.logQ)\n        for u in c.lev:\n            if len(u) == 0: continue\n            g, t, x, p = c.g[u], c.t[u], c.x[u], c.par[u]\n            op = logo[p] + logb[p]                                     # parent: outside + all its children\n            cP.index_put_((g, t, x), torch.exp(op - Zn[p][:, None]), accumulate=True)\n            ii = torch.nonzero(c.internal[u])[:, 0]\n            for j in ii.split(self.chunk()):\n                uu = u[j]; gi, xi, pi_ = g[j], x[j], p[j]\n                rest = op[j] - LM[uu] + self.logP[gi, t[j], xi]           # parent side, this child\'s symbol drawn\n                q = self.logQ[gi, xi]\n                pair = rest[:, :, None] + q + logb[c.node[uu]][:, None, :] - Zn[pi_][:, None, None]\n                cQ.index_put_((gi, xi), torch.exp(pair), accumulate=True)\n                logo[c.node[uu]] = torch.logsumexp(rest[:, :, None] + q, dim=1)\n        cpi = torch.exp(self.logpi + logb[c.roots] - Z[:, None]).sum(0)\n        return cP, cQ, cpi, float(Z.double().sum())\n\n    # ------------------------------------------------------------------ learning\n    def mstep(self, cP, cQ, cpi):\n        m = self.m[None, None, :, None]\n        self.logP = torch.log((cP + self.a * m) / (cP.sum(2, keepdim=True) + self.a))\n        self.logQ = torch.log((cQ + self.b) / (cQ.sum(3, keepdim=True) + self.H * self.b))\n        self.logpi = torch.log((cpi + 1e-3) / (cpi.sum() + self.H * 1e-3))\n\n    def set_marginal(self, c):\n        m = torch.as_tensor(c.xcount + 1.0, device=self.dev, dtype=torch.float32)\n        self.m = m / m.sum()\n\n    def em(self, c, iters, tol=1e-6, log=None):\n        prev = -math.inf; hist = []\n        for it in range(iters):\n            cP, cQ, cpi, ll = self.estep(c)\n            self.mstep(cP, cQ, cpi)\n            hist.append(ll)\n            if log: log(it=it, H=self.H, train_ll_per_unit=ll / c.n_units)\n            if ll - prev < tol * abs(ll): break\n            prev = ll\n        return hist\n\n    def split(self, rng, eps=0.1):\n        """H -> 2H: duplicate every type, perturb the copies\' symbol laws, split each child type\'s mass in two"""\n        H2 = 2 * self.H\n        noise = lambda shape: torch.as_tensor(rng.normal(0, eps, shape), device=self.dev, dtype=torch.float32)\n        P = self.logP.repeat_interleave(2, dim=3) + noise(self.logP.shape[:3] + (H2,))\n        self.logP = P - torch.logsumexp(P, dim=2, keepdim=True)\n        Q = self.logQ.repeat_interleave(2, dim=2).repeat_interleave(2, dim=3) - math.log(2)\n        Q = Q + noise(Q.shape)\n        self.logQ = Q - torch.logsumexp(Q, dim=3, keepdim=True)\n        pi = self.logpi.repeat_interleave(2) - math.log(2)\n        self.logpi = pi - torch.logsumexp(pi, 0)\n        self.H = H2\n\n    def state(self):\n        return (self.logP.clone(), self.logQ.clone(), self.logpi.clone(), self.H)\n\n    def load_state(self, s):\n        self.logP, self.logQ, self.logpi, self.H = s[0].clone(), s[1].clone(), s[2].clone(), s[3]\n')
"""Learning curves of the latent tree model on Python ASTs (where.tex sec. prog-latent), H = 1..16 by splitting.
Train on N random files of the pool (validation files excluded), report validation and test nats per unit per H.
Run locally:  python exp_code_latent.py [smoke]      Colab: bundle with make_bundle.py (see run_code_latent.sh)
"""
import json, math, os, sys, time
import numpy as np
import torch
import astdata
from code_latent import Corpus, LatentTree

BUDGET = float(os.environ.get("BUDGET_SECONDS", "1e9")); T0 = time.time()
DEV = "cuda" if torch.cuda.is_available() else "cpu"
N_VAL = 20
H_MAX = int(os.environ.get("H_MAX", "16"))
EM_ITERS, PROBE_ITERS, RESTARTS, TOL = 40, 6, 2, 1e-5


def log(**k):
    k["t"] = round(time.time() - T0, 1); print(json.dumps(k), flush=True)
    if os.environ.get("PROGRESS_FILE"):
        with open(os.environ["PROGRESS_FILE"], "a") as f:
            f.write(json.dumps(k) + "\n")


def nats(m, c):
    return -m.loglik(c) / c.n_units


def curve_point(d, files, val, te, seed):
    rng = np.random.default_rng(1000 + seed)
    tr = Corpus(d, files, DEV)
    m = LatentTree(4, len(d["contexts"]), len(d["symbols"]), 1, DEV)
    m.set_marginal(tr)
    m.em(tr, 3)
    out = {1: (nats(m, val), nats(m, te), -m.loglik(tr) / tr.n_units)}
    while m.H < H_MAX and time.time() - T0 < BUDGET - 300:
        base = m.state(); best = None
        for r in range(RESTARTS):
            m.load_state(base); m.split(rng)
            h = m.em(tr, PROBE_ITERS, tol=TOL)
            if best is None or h[-1] > best[0]:
                best = (h[-1], m.state())
        m.load_state(best[1])
        hist = m.em(tr, EM_ITERS, tol=TOL)
        out[m.H] = (nats(m, val), nats(m, te), -m.loglik(tr) / tr.n_units)
        log(stage=True, files=len(files), seed=seed, H=m.H, em_iters=len(hist), val=round(out[m.H][0], 5), test=round(out[m.H][1], 5))
    return tr.n_units, out


def main():
    smoke = "smoke" in sys.argv or os.environ.get("SMOKE") == "1"
    d = astdata.load()
    test, pool = astdata.split(d)
    rs = np.random.default_rng(7)
    val = rs.choice(pool, N_VAL, replace=False); pool = np.setdiff1d(pool, val)
    if smoke:
        test = test[:40]
    val_c, te_c = Corpus(d, val, DEV), Corpus(d, test, DEV)
    log(dev=DEV, pool=len(pool), test_units=te_c.n_units, val_units=val_c.n_units)
    sizes = [2, 4] if smoke else [1, 4, 16, 64, 256, len(pool)]
    if os.environ.get("FILES"):
        sizes = [min(int(v), len(pool)) for v in os.environ["FILES"].split(",")]
    global H_MAX
    if smoke: H_MAX = 4
    for n in sizes:
        for s in range(1 if n == len(pool) else 2):
            if time.time() - T0 > BUDGET - 300:
                log(stopped="budget"); return
            files = np.random.default_rng(100 * n + s).choice(pool, n, replace=False)
            units, out = curve_point(d, files, val_c, te_c, s)
            best = min(out, key=lambda h: out[h][0])
            log(files=n, seed=s, train_units=units,
                by_H={h: {"val": round(v[0], 5), "test": round(v[1], 5), "train": round(v[2], 5)} for h, v in out.items()},
                best_H=best, best_test=round(out[best][1], 5))


if __name__ == "__main__":
    main()
